    uint16_t *gate_out = static_cast<uint16_t *>(b4);
    uint16_t *gate_res = static_cast<uint16_t *>(b0);

    uint column = (blockIdx.x * blockDim.x + threadIdx.x);
    uint row = (blockIdx.y * blockDim.y + threadIdx.y);
    if (row >= args.rows || column >= args.width) return;
    uint base = gate_map[row] * args.slots * args.width;
    float gate = H3_BF16_TO_F32(
        gate_mod[base + args.gate_slot * args.width + column]);
    uint index = row * args.width + column;
    float value = H3_BF16_TO_F32(gate_res[index]) +
                  H3_BF16_TO_F32(gate_branch[index]) * gate;
    gate_out[index] = uint16_t(h3_f32_to_bf16(value));

}

__global__ void main_gate_adaln_bf16(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    uint16_t *gad_branch = static_cast<uint16_t *>(b1);
    uint16_t *gad_gated = static_cast<uint16_t *>(b6);
    uint16_t *gad_gmod = static_cast<uint16_t *>(b2);
    uint32_t *gad_map = static_cast<uint32_t *>(b3);
    uint16_t *gad_nmod = static_cast<uint16_t *>(b5);
    uint16_t *gad_out = static_cast<uint16_t *>(b7);
    uint16_t *gad_res = static_cast<uint16_t *>(b0);
    uint16_t *gad_w = static_cast<uint16_t *>(b4);
    __shared__ uint16_t gated_values[5376];
    __shared__ float norm_reductions[256];

    uint row = blockIdx.x;
    uint tid = threadIdx.x;
    if (row >= args.rows) return;
    uint base_row = row * args.width;
    uint base = gad_map[row] * args.slots * args.width;
    float local_sum = 0.0f;
    for (uint column = tid; column < args.width; column += 256u) {
        uint index = base_row + column;
        float gate = H3_BF16_TO_F32(
            gad_gmod[base + args.gate_slot * args.width +
                          column]);
        uint16_t gated = uint16_t(h3_f32_to_bf16(
            H3_BF16_TO_F32(gad_res[index]) +
            H3_BF16_TO_F32(gad_branch[index]) * gate));
        gad_gated[index] = gated;
        gated_values[column] = gated;
        float value = H3_BF16_TO_F32(gated);
        local_sum = fmaf(value, value, local_sum);
    }
    norm_reductions[tid] = local_sum;
    __syncthreads();
    for (uint stride = 128u; stride > 0u; stride >>= 1) {
        if (tid < stride) norm_reductions[tid] += norm_reductions[tid + stride];
        __syncthreads();
    }
    float inverse = h3_rsqrt(norm_reductions[0] / float(args.width) +
                                args.epsilon);
    for (uint column = tid; column < args.width; column += 256u) {
        float normalized = H3_BF16_TO_F32(gated_values[column]) * inverse *
                           H3_BF16_TO_F32(gad_w[column]);
        float shift = H3_BF16_TO_F32(
            gad_nmod[base + args.shift_slot * args.width +
                          column]);
        float scale = H3_BF16_TO_F32(
            gad_nmod[base + args.scale_slot * args.width +
                          column]);
        gad_out[base_row + column] = uint16_t(h3_f32_to_bf16(
            normalized * (1.0f + scale) + shift));
    }

}

__global__ void main_rms_inverse_bf16(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    uint16_t *rms_in = static_cast<uint16_t *>(b0);
    float *rms_inv = static_cast<float *>(b1);
    __shared__ float norm_reductions[256];

    uint row = blockIdx.x;
    uint tid = threadIdx.x;
    if (row >= args.rows) return;
    uint base_row = row * args.width;
    float local_sum = 0.0f;
    for (uint k = tid; k < args.width; k += 256u) {
        float value = H3_BF16_TO_F32(rms_in[base_row + k]);
        local_sum = fmaf(value, value, local_sum);
    }
    norm_reductions[tid] = local_sum;
    __syncthreads();
    for (uint stride = 128u; stride > 0u; stride >>= 1) {
        if (tid < stride) norm_reductions[tid] += norm_reductions[tid + stride];
        __syncthreads();
    }
    if (tid == 0u) {
        rms_inv[row] = h3_rsqrt(norm_reductions[0] /
                                        float(args.width) +
                                        args.epsilon);
    }

}

__global__ void main_adaln_linear_bf16(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    uint16_t *al_b = static_cast<uint16_t *>(b6);
    uint16_t *al_in = static_cast<uint16_t *>(b0);
    float *al_inv = static_cast<float *>(b1);
    uint32_t *al_map = static_cast<uint32_t *>(b4);
    uint16_t *al_mod = static_cast<uint16_t *>(b3);
    uint16_t *al_nw = static_cast<uint16_t *>(b2);
    uint16_t *al_out = static_cast<uint16_t *>(b7);
    uint16_t *al_w = static_cast<uint16_t *>(b5);
    __shared__ float lin_input_tile[16][16];
    __shared__ float lin_weight_tile[16][16];

    uint column = blockIdx.x * 16u + threadIdx.x;
    uint row = blockIdx.y * 16u + threadIdx.y;
    float sum = (args.has_bias != 0u && column < args.output_dim) ?
        H3_BF16_TO_F32(al_b[column]) : 0.0f;
    uint base = row < args.rows ?
        al_map[row] * args.slots * args.width : 0u;
    uint tile_count = (args.width + 15u) / 16u;
    for (uint tile = 0u; tile < tile_count; tile++) {
        uint input_k = tile * 16u + threadIdx.x;
        uint16_t normalized = uint16_t(0);
        if (row < args.rows && input_k < args.width) {
            float value = H3_BF16_TO_F32(
                al_in[row * args.width + input_k]);
            float shift = H3_BF16_TO_F32(
                al_mod[base + args.shift_slot * args.width +
                            input_k]);
            float scale = H3_BF16_TO_F32(
                al_mod[base + args.scale_slot * args.width +
                            input_k]);
            float normed = value * al_inv[row] *
                           H3_BF16_TO_F32(al_nw[input_k]);
            normalized = uint16_t(h3_f32_to_bf16(normed * (1.0f + scale) +
                                                 shift));
        }
        lin_input_tile[threadIdx.y][threadIdx.x] =
            H3_BF16_TO_F32(normalized);
        uint weight_k = tile * 16u + threadIdx.y;
        lin_weight_tile[threadIdx.y][threadIdx.x] =
            (column < args.output_dim && weight_k < args.width) ?
            H3_BF16_TO_F32(al_w[column * args.width + weight_k]) :
            0.0f;
        __syncthreads();
        for (uint k = 0u; k < 16u; k++) {
            sum = fmaf(lin_input_tile[threadIdx.y][k],
                      lin_weight_tile[k][threadIdx.x], sum);
        }
        __syncthreads();
    }
    if (row < args.rows && column < args.output_dim) {
        al_out[row * args.output_dim + column] =
            uint16_t(h3_f32_to_bf16(sum));
    }

}

__global__ void main_head_rms_norm_bf16(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    uint16_t *hn_in = static_cast<uint16_t *>(b0);
    uint16_t *hn_w = static_cast<uint16_t *>(b1);

    uint row = (blockIdx.x * blockDim.x + threadIdx.x);
    uint head = (blockIdx.y * blockDim.y + threadIdx.y);
    if (row >= args.rows || head >= args.width) return;
    uint base = (row * args.width + head) * args.input_dim;
    float sum = 0.0f;
    for (uint d = 0u; d < args.input_dim; d++) {
        float value = H3_BF16_TO_F32(hn_in[base + d]);
        sum = fmaf(value, value, sum);
    }
    float inverse = h3_rsqrt(sum / float(args.input_dim) +
                                args.epsilon);
    for (uint d = 0u; d < args.input_dim; d++) {
        float value = H3_BF16_TO_F32(hn_in[base + d]);
        hn_in[base + d] = uint16_t(h3_f32_to_bf16(
            value * inverse * H3_BF16_TO_F32(hn_w[d])));
    }

}

__global__ void main_grouped_qkv_rope_bf16(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    uint16_t *k_norm = static_cast<uint16_t *>(b2);
    uint16_t *key_out = static_cast<uint16_t *>(b6);
    uint16_t *q_norm = static_cast<uint16_t *>(b1);
    uint16_t *qkv_in = static_cast<uint16_t *>(b0);
    uint16_t *query_out = static_cast<uint16_t *>(b5);
    uint16_t *rope_cos = static_cast<uint16_t *>(b3);
    uint16_t *rope_sin = static_cast<uint16_t *>(b4);
    uint16_t *value_out = static_cast<uint16_t *>(b7);

    uint dimension = (blockIdx.x * blockDim.x + threadIdx.x);
    uint head = (blockIdx.y * blockDim.y + threadIdx.y);
    uint row = (blockIdx.z * blockDim.z + threadIdx.z);
    if (dimension >= args.input_dim || head >= args.width ||
        row >= args.rows)
        return;
    uint inner = args.width * args.input_dim;
    uint row_base = row * inner * 3u;
    uint q_base = row_base + head * args.input_dim;
    uint k_base = q_base + inner;
    uint v_base = q_base + inner * 2u;
    if (args.grouped != 0u) {
        q_base = row_base + head * args.input_dim * 3u;
        k_base = q_base + args.input_dim;
        v_base = k_base + args.input_dim;
    }
    float q_sum = 0.0f;
    float k_sum = 0.0f;
    for (uint d = 0u; d < args.input_dim; d++) {
        float q = H3_BF16_TO_F32(qkv_in[q_base + d]);
        float k = H3_BF16_TO_F32(qkv_in[k_base + d]);
        q_sum = fmaf(q, q, q_sum);
        k_sum = fmaf(k, k, k_sum);
    }
    float q_inverse = h3_rsqrt(q_sum / float(args.input_dim) +
                                  args.epsilon);
    float k_inverse = h3_rsqrt(k_sum / float(args.input_dim) +
                                  args.epsilon);
    float q0 = H3_BF16_TO_F32(qkv_in[q_base + dimension]) * q_inverse *
               H3_BF16_TO_F32(q_norm[dimension]);
    float k0 = H3_BF16_TO_F32(qkv_in[k_base + dimension]) * k_inverse *
               H3_BF16_TO_F32(k_norm[dimension]);
    if (dimension < args.output_dim) {
        uint pair = dimension + args.output_dim;
        float q1 = H3_BF16_TO_F32(qkv_in[q_base + pair]) * q_inverse *
                   H3_BF16_TO_F32(q_norm[pair]);
        float k1 = H3_BF16_TO_F32(qkv_in[k_base + pair]) * k_inverse *
                   H3_BF16_TO_F32(k_norm[pair]);
        float c = H3_BF16_TO_F32(rope_cos[row * args.output_dim +
                                               dimension]);
        float s = H3_BF16_TO_F32(rope_sin[row * args.output_dim +
                                               dimension]);
        q0 = q0 * c - q1 * s;
        k0 = k0 * c - k1 * s;
    } else if (dimension < args.output_dim * 2u) {
        uint pair = dimension - args.output_dim;
        float q1 = H3_BF16_TO_F32(qkv_in[q_base + pair]) * q_inverse *
                   H3_BF16_TO_F32(q_norm[pair]);
        float k1 = H3_BF16_TO_F32(qkv_in[k_base + pair]) * k_inverse *
                   H3_BF16_TO_F32(k_norm[pair]);
        float c = H3_BF16_TO_F32(rope_cos[row * args.output_dim +
                                               pair]);
        float s = H3_BF16_TO_F32(rope_sin[row * args.output_dim +
                                               pair]);
        q0 = q0 * c + q1 * s;
        k0 = k0 * c + k1 * s;
    }
    uint output_index = (row * args.width + head) * args.input_dim +
                        dimension;
    query_out[output_index] = uint16_t(h3_f32_to_bf16(q0));
    key_out[output_index] = uint16_t(h3_f32_to_bf16(k0));
    value_out[output_index] = qkv_in[v_base + dimension];

}

__global__ void main_sdpa_bf16(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    uint16_t *sdpa_k = static_cast<uint16_t *>(b1);
    uint16_t *sdpa_out = static_cast<uint16_t *>(b3);
    uint16_t *sdpa_q = static_cast<uint16_t *>(b0);
    uint16_t *sdpa_v = static_cast<uint16_t *>(b2);

    uint head = (blockIdx.x * blockDim.x + threadIdx.x);
    uint row = (blockIdx.y * blockDim.y + threadIdx.y);
    uint seq = args.rows;
    uint heads = args.width;
    uint dim = args.input_dim;
    if (row >= seq || head >= heads) return;
    float scale = args.left_scale;
    uint qbase = (row * heads + head) * dim;
    float maxv = -3.402823466e+38f;
    for (uint s = 0u; s < seq; s++) {
        uint kbase = (s * heads + head) * dim;
        float dot = 0.0f;
        for (uint d = 0u; d < dim; d++) {
            dot = fmaf(H3_BF16_TO_F32(sdpa_q[qbase + d]),
                      H3_BF16_TO_F32(sdpa_k[kbase + d]), dot);
        }
        dot *= scale;
        maxv = h3_max(maxv, dot);
    }
    float sum = 0.0f;
    for (uint s = 0u; s < seq; s++) {
        uint kbase = (s * heads + head) * dim;
        float dot = 0.0f;
        for (uint d = 0u; d < dim; d++) {
            dot = fmaf(H3_BF16_TO_F32(sdpa_q[qbase + d]),
                      H3_BF16_TO_F32(sdpa_k[kbase + d]), dot);
        }
        sum += expf(dot * scale - maxv);
    }
    for (uint d = 0u; d < dim; d++) {
        float acc = 0.0f;
        for (uint s = 0u; s < seq; s++) {
            uint kbase = (s * heads + head) * dim;
            float dot = 0.0f;
            for (uint k = 0u; k < dim; k++) {
                dot = fmaf(H3_BF16_TO_F32(sdpa_q[qbase + k]),
                          H3_BF16_TO_F32(sdpa_k[kbase + k]), dot);
            }
            acc = fmaf(expf(dot * scale - maxv),
                      H3_BF16_TO_F32(sdpa_v[kbase + d]), acc);
        }
        uint oindex = args.grouped != 0u ?
            (head * seq + row) * dim + d : qbase + d;
        sdpa_out[oindex] = uint16_t(h3_f32_to_bf16(acc / sum));
    }

}

__global__ void main_sdpa_flash_bf16(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    uint16_t *fl_k = static_cast<uint16_t *>(b1);
    uint16_t *fl_out = static_cast<uint16_t *>(b3);
    uint16_t *fl_q = static_cast<uint16_t *>(b0);
    uint16_t *fl_v = static_cast<uint16_t *>(b2);
    __shared__ float fl_acc[128];
    __shared__ float fl_dots[128];
    __shared__ float fl_max;
    __shared__ float fl_old_max;
    __shared__ float fl_q_shared[128];
    __shared__ float fl_sum;

    uint head = blockIdx.x;
    uint row = blockIdx.y;
    uint d = threadIdx.x;
    uint seq = args.rows;
    uint heads = args.width;
    uint dim = args.input_dim;
    if (row >= seq || head >= heads || d >= dim) return;
    float scale = args.left_scale;
    uint qbase = (row * heads + head) * dim;
    fl_q_shared[d] = H3_BF16_TO_F32(fl_q[qbase + d]);
    fl_acc[d] = 0.0f;
    if (d == 0u) {
        fl_max = -3.402823466e+38f;
        fl_sum = 0.0f;
    }
    __syncthreads();
    for (uint s = 0u; s < seq; s++) {
        uint kbase = (s * heads + head) * dim;
        fl_dots[d] = fmaf(fl_q_shared[d],
                         H3_BF16_TO_F32(fl_k[kbase + d]), 0.0f);
        __syncthreads();
        for (uint stride = 64u; stride > 0u; stride >>= 1) {
            if (d < stride) fl_dots[d] += fl_dots[d + stride];
            __syncthreads();
        }
        float dot = fl_dots[0] * scale;
        if (d == 0u) {
            float new_max = h3_max(fl_max, dot);
            fl_old_max = fl_max;
            fl_max = new_max;
            fl_sum = fl_sum * expf(fl_old_max - new_max) +
                     expf(dot - new_max);
        }
        __syncthreads();
        float p = expf(fl_old_max - fl_max);
        float w = expf(fl_dots[0] * scale - fl_max);
        fl_acc[d] = fl_acc[d] * p +
                    w * H3_BF16_TO_F32(fl_v[kbase + d]);
        __syncthreads();
    }
    uint oindex = args.grouped != 0u ?
        (head * seq + row) * dim + d : qbase + d;
    fl_out[oindex] = uint16_t(h3_f32_to_bf16(fl_acc[d] / fl_sum));

}

