__global__ void main_token_pool_bf16(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    uint16_t *tp_base = static_cast<uint16_t *>(b3);
    uint32_t *tp_base_idx = static_cast<uint32_t *>(b4);
    uint16_t *tp_in = static_cast<uint16_t *>(b0);
    uint16_t *tp_orig = static_cast<uint16_t *>(b5);
    uint16_t *tp_out = static_cast<uint16_t *>(b2);
    uint2 *tp_pairs = static_cast<uint2 *>(b1);

    uint column = (blockIdx.x * blockDim.x + threadIdx.x);
    uint row = (blockIdx.y * blockDim.y + threadIdx.y);
    if (row >= args.rows || column >= args.width) return;
    uvec2 pair = tp_pairs[row];
    uint16_t first = tp_in[args.sample_offset +
                                pair.x * args.width + column];
    tp_orig[args.tokens + pair.x * args.width + column] =
        first;
    uint16_t pooled = first;
    if (pair.x != pair.y) {
        uint16_t second = tp_in[args.sample_offset +
                                     pair.y * args.width + column];
        tp_orig[args.tokens + pair.y * args.width + column] =
            second;
        float average = (H3_BF16_TO_F32(first) + H3_BF16_TO_F32(second)) *
                        0.5f;
        pooled = uint16_t(h3_f32_to_bf16(average));
    }
    tp_out[row * args.width + column] = pooled;
    uint baseline_index = tp_base_idx[row];
    if (baseline_index != 0xffffffffu) {
        tp_base[args.vocab_size +
                     baseline_index * args.width + column] = pooled;
    }

}

__global__ void main_token_pool_adaln_bf16(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    uint16_t *tp_adout = static_cast<uint16_t *>(b9);
    uint16_t *tp_base = static_cast<uint16_t *>(b3);
    uint32_t *tp_base_idx = static_cast<uint32_t *>(b4);
    uint16_t *tp_in = static_cast<uint16_t *>(b0);
    uint32_t *tp_map = static_cast<uint32_t *>(b8);
    uint16_t *tp_mod = static_cast<uint16_t *>(b7);
    uint16_t *tp_orig = static_cast<uint16_t *>(b5);
    uint16_t *tp_out = static_cast<uint16_t *>(b2);
    uint2 *tp_pairs = static_cast<uint2 *>(b1);
    uint16_t *tp_w = static_cast<uint16_t *>(b6);
    __shared__ uint16_t gated_values[5376];
    __shared__ float norm_reductions[256];

    uint row = blockIdx.x;
    uint tid = threadIdx.x;
    if (row >= args.rows) return;
    uvec2 pair = tp_pairs[row];
    uint baseline_index = tp_base_idx[row];
    float local_sum = 0.0f;
    for (uint column = tid; column < args.width; column += 256u) {
        uint16_t first = tp_in[args.sample_offset +
                                    pair.x * args.width + column];
        tp_orig[args.tokens + pair.x * args.width + column] =
            first;
        uint16_t pooled = first;
        if (pair.x != pair.y) {
            uint16_t second = tp_in[args.sample_offset +
                                         pair.y * args.width + column];
            tp_orig[args.tokens +
                         pair.y * args.width + column] = second;
            pooled = uint16_t(h3_f32_to_bf16(
                (H3_BF16_TO_F32(first) + H3_BF16_TO_F32(second)) * 0.5f));
        }
        uint destination = row * args.width + column;
        tp_out[destination] = pooled;
        gated_values[column] = pooled;
        if (baseline_index != 0xffffffffu) {
            tp_base[args.vocab_size +
                         baseline_index * args.width + column] = pooled;
        }
        float value = H3_BF16_TO_F32(pooled);
        local_sum = fmaf(value, value, local_sum);
    }
    norm_reductions[tid] = local_sum;
    __syncthreads();
    for (uint stride = 128u; stride > 0u; stride >>= 1) {
        if (tid < stride) norm_reductions[tid] += norm_reductions[tid + stride];
        __syncthreads();
    }
    float inverse = h3_rsqrt(norm_reductions[0] / float(args.width) +
                                args.epsilon);
    uint base = tp_map[row] * args.slots * args.width;
    for (uint column = tid; column < args.width; column += 256u) {
        float normalized = H3_BF16_TO_F32(gated_values[column]) * inverse *
                           H3_BF16_TO_F32(tp_w[column]);
        float shift = H3_BF16_TO_F32(
            tp_mod[base + args.shift_slot * args.width +
                        column]);
        float scale = H3_BF16_TO_F32(
            tp_mod[base + args.scale_slot * args.width +
                        column]);
        tp_adout[row * args.width + column] =
            uint16_t(h3_f32_to_bf16(normalized * (1.0f + scale) + shift));
    }

}

__global__ void main_token_expand_delta_bf16(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    uint16_t *tx_base = static_cast<uint16_t *>(b2);
    uint32_t *tx_base_idx = static_cast<uint32_t *>(b3);
    uint16_t *tx_orig = static_cast<uint16_t *>(b0);
    uint16_t *tx_out = static_cast<uint16_t *>(b5);
    uint32_t *tx_parents = static_cast<uint32_t *>(b4);
    uint16_t *tx_reduced = static_cast<uint16_t *>(b1);

    uint column = (blockIdx.x * blockDim.x + threadIdx.x);
    uint row = (blockIdx.y * blockDim.y + threadIdx.y);
    if (row >= args.rows || column >= args.width) return;
    uint parent = tx_parents[row];
    uint destination = row * args.width + column;
    uint reduced_index = parent * args.width + column;
    if (row < args.elements) {
        tx_out[destination] = tx_reduced[reduced_index];
        return;
    }
    uint baseline_row = tx_base_idx[parent];
    if (baseline_row == 0xffffffffu) {
        tx_out[destination] = tx_reduced[reduced_index];
        return;
    }
    uint baseline_index = args.vocab_size +
                          baseline_row * args.width + column;
    float update = H3_BF16_TO_F32(tx_reduced[reduced_index]) -
                   H3_BF16_TO_F32(tx_base[baseline_index]);
    tx_out[destination] = uint16_t(h3_f32_to_bf16(
        H3_BF16_TO_F32(tx_orig[args.tokens + destination]) +
        args.left_scale * update));

}

__global__ void main_token_expand_adaln_bf16(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    uint16_t *tx_adout = static_cast<uint16_t *>(b9);
    uint16_t *tx_base = static_cast<uint16_t *>(b2);
    uint32_t *tx_base_idx = static_cast<uint32_t *>(b3);
    uint32_t *tx_map = static_cast<uint32_t *>(b8);
    uint16_t *tx_mod = static_cast<uint16_t *>(b7);
    uint16_t *tx_orig = static_cast<uint16_t *>(b0);
    uint16_t *tx_out = static_cast<uint16_t *>(b5);
    uint32_t *tx_parents = static_cast<uint32_t *>(b4);
    uint16_t *tx_reduced = static_cast<uint16_t *>(b1);
    uint16_t *tx_w = static_cast<uint16_t *>(b6);
    __shared__ uint16_t gated_values[5376];
    __shared__ float norm_reductions[256];

    uint row = blockIdx.x;
    uint tid = threadIdx.x;
    if (row >= args.rows) return;
    uint parent = tx_parents[row];
    uint baseline_row = tx_base_idx[parent];
    bool direct = row < args.elements ||
                  baseline_row == 0xffffffffu;
    float local_sum = 0.0f;
    for (uint column = tid; column < args.width; column += 256u) {
        uint destination = row * args.width + column;
        uint reduced_index = parent * args.width + column;
        uint16_t restored = tx_reduced[reduced_index];
        if (!direct) {
            uint baseline_index = args.vocab_size +
                                  baseline_row * args.width + column;
            float update = H3_BF16_TO_F32(restored) -
                           H3_BF16_TO_F32(tx_base[baseline_index]);
            restored = uint16_t(h3_f32_to_bf16(
                H3_BF16_TO_F32(tx_orig[args.tokens + destination]) +
                args.left_scale * update));
        }
        gated_values[column] = restored;
        tx_out[destination] = restored;
        float value = H3_BF16_TO_F32(restored);
        local_sum = fmaf(value, value, local_sum);
    }
    norm_reductions[tid] = local_sum;
    __syncthreads();
    for (uint stride = 128u; stride > 0u; stride >>= 1) {
        if (tid < stride) norm_reductions[tid] += norm_reductions[tid + stride];
        __syncthreads();
    }
    float inverse = h3_rsqrt(norm_reductions[0] / float(args.width) +
                                args.epsilon);
    uint base = tx_map[row] * args.slots * args.width;
    for (uint column = tid; column < args.width; column += 256u) {
        float normalized = H3_BF16_TO_F32(gated_values[column]) * inverse *
                           H3_BF16_TO_F32(tx_w[column]);
        float shift = H3_BF16_TO_F32(
            tx_mod[base + args.shift_slot * args.width +
                        column]);
        float scale = H3_BF16_TO_F32(
            tx_mod[base + args.scale_slot * args.width +
                        column]);
        tx_adout[row * args.width + column] =
            uint16_t(h3_f32_to_bf16(normalized * (1.0f + scale) + shift));
    }

}

__global__ void main_text_qk_rope_bf16(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    uint16_t *tk_in = static_cast<uint16_t *>(b1);
    uint16_t *tk_out = static_cast<uint16_t *>(b7);
    uint16_t *tk_w = static_cast<uint16_t *>(b3);
    uint16_t *tq_in = static_cast<uint16_t *>(b0);
    uint16_t *tq_out = static_cast<uint16_t *>(b6);
    uint16_t *tq_rc = static_cast<uint16_t *>(b4);
    uint16_t *tq_rs = static_cast<uint16_t *>(b5);
    uint16_t *tq_w = static_cast<uint16_t *>(b2);

    uint dimension = (blockIdx.x * blockDim.x + threadIdx.x);
    uint head = (blockIdx.y * blockDim.y + threadIdx.y);
    uint row = (blockIdx.z * blockDim.z + threadIdx.z);
    uint query_heads = args.width;
    uint kv_heads = args.input_dim;
    uint head_dim = args.output_dim;
    if (dimension >= head_dim || head >= query_heads ||
        row >= args.rows)
        return;
    uint half_dim = head_dim / 2u;
    uint pair = dimension < half_dim ? dimension + half_dim :
                                        dimension - half_dim;
    float c = H3_BF16_TO_F32(tq_rc[row * half_dim +
                                        (dimension % half_dim)]);
    float s = H3_BF16_TO_F32(tq_rs[row * half_dim +
                                        (dimension % half_dim)]);
    uint q_base = (row * query_heads + head) * head_dim;
    float q_sum = 0.0f;
    for (uint d = 0u; d < head_dim; d++) {
        float value = H3_BF16_TO_F32(tq_in[q_base + d]);
        q_sum = fmaf(value, value, q_sum);
    }
    float q_inverse = h3_rsqrt(q_sum / float(head_dim) +
                                  args.epsilon);
    float q0 = H3_BF16_TO_F32(tq_in[q_base + dimension]) * q_inverse *
               H3_BF16_TO_F32(tq_w[dimension]);
    float q1 = H3_BF16_TO_F32(tq_in[q_base + pair]) * q_inverse *
               H3_BF16_TO_F32(tq_w[pair]);
    float q_rotated = dimension < half_dim ? q0 * c - q1 * s :
                                             q0 * c + q1 * s;
    tq_out[q_base + dimension] = uint16_t(h3_f32_to_bf16(q_rotated));
    if (head < kv_heads) {
        uint k_base = (row * kv_heads + head) * head_dim;
        float k_sum = 0.0f;
        for (uint d = 0u; d < head_dim; d++) {
            float value = H3_BF16_TO_F32(tk_in[k_base + d]);
            k_sum = fmaf(value, value, k_sum);
        }
        float k_inverse = h3_rsqrt(k_sum / float(head_dim) +
                                      args.epsilon);
        float k0 = H3_BF16_TO_F32(tk_in[k_base + dimension]) *
                   k_inverse * H3_BF16_TO_F32(tk_w[dimension]);
        float k1 = H3_BF16_TO_F32(tk_in[k_base + pair]) * k_inverse *
                   H3_BF16_TO_F32(tk_w[pair]);
        float k_rotated = dimension < half_dim ? k0 * c - k1 * s :
                                                 k0 * c + k1 * s;
        tk_out[k_base + dimension] = uint16_t(h3_f32_to_bf16(k_rotated));
    }

}

__global__ void main_rope_text_bf16(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    float *tr_c = static_cast<float *>(b2);
    uint16_t *tr_k = static_cast<uint16_t *>(b1);
    uint16_t *tr_q = static_cast<uint16_t *>(b0);
    float *tr_s = static_cast<float *>(b3);

    uint row = (blockIdx.x * blockDim.x + threadIdx.x);
    uint head = (blockIdx.y * blockDim.y + threadIdx.y);
    uint query_heads = args.width;
    uint kv_heads = args.input_dim;
    uint head_dim = args.output_dim;
    if (row >= args.rows) return;
    uint half_dim = head_dim / 2u;
    if (head < query_heads) {
        uint base = (row * query_heads + head) * head_dim;
        for (uint d = 0u; d < half_dim; d++) {
            float first = H3_BF16_TO_F32(tr_q[base + d]);
            float second = H3_BF16_TO_F32(tr_q[base + half_dim + d]);
            float c = tr_c[row * half_dim + d];
            float s = tr_s[row * half_dim + d];
            tr_q[base + d] = uint16_t(h3_f32_to_bf16(first * c -
                                                          second * s));
            tr_q[base + half_dim + d] =
                uint16_t(h3_f32_to_bf16(second * c + first * s));
        }
    }
    if (head < kv_heads) {
        uint base = (row * kv_heads + head) * head_dim;
        for (uint d = 0u; d < half_dim; d++) {
            float first = H3_BF16_TO_F32(tr_k[base + d]);
            float second = H3_BF16_TO_F32(tr_k[base + half_dim + d]);
            float c = tr_c[row * half_dim + d];
            float s = tr_s[row * half_dim + d];
            tr_k[base + d] = uint16_t(h3_f32_to_bf16(first * c -
                                                          second * s));
            tr_k[base + half_dim + d] =
                uint16_t(h3_f32_to_bf16(second * c + first * s));
        }
    }

}

__global__ void main_gqa_causal_bf16(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    uint16_t *gq_k = static_cast<uint16_t *>(b1);
    uint16_t *gq_out = static_cast<uint16_t *>(b3);
    uint16_t *gq_q = static_cast<uint16_t *>(b0);
    uint16_t *gq_v = static_cast<uint16_t *>(b2);
    __shared__ float gq_online_state[3];
    __shared__ float gq_reductions[128];
    __shared__ float gq_scores[4096];
    __shared__ float gq_shared_query[128];

    uint query_row = blockIdx.x;
    uint query_head = blockIdx.y;
    uint tid = threadIdx.x;
    uint seq = args.rows;
    uint query_heads = args.width;
    uint kv_heads = args.input_dim;
    uint head_dim = args.output_dim;
    if (query_row >= seq || query_head >= query_heads) return;
    uint kv_head = query_head / (query_heads / kv_heads);
    uint q_base = (query_row * query_heads + query_head) * head_dim;
    uint key_count = query_row + 1;
    for (uint d = tid; d < head_dim; d += 128u) {
        gq_shared_query[d] = H3_BF16_TO_F32(uint16_t(h3_f32_to_bf16(
            H3_BF16_TO_F32(gq_q[q_base + d]) * args.left_scale)));
    }
    __syncthreads();

    if (seq > 4096u) {
        float accumulator = 0.0f;
        if (tid == 0u) {
            gq_online_state[0] = -3.402823466e+38f;
            gq_online_state[1] = 0.0f;
            gq_online_state[2] = 0.0f;
        }
        __syncthreads();
        for (uint tile_start = 0u; tile_start < key_count;
             tile_start += 128u) {
            uint key_row = tile_start + tid;
            float dot = -3.402823466e+38f;
            if (key_row < key_count) {
                uint k_base =
                    (key_row * kv_heads + kv_head) * head_dim;
                dot = 0.0f;
                for (uint d = 0u; d < head_dim; d++) {
                    dot = fmaf(gq_shared_query[d],
                              H3_BF16_TO_F32(gq_k[k_base + d]), dot);
                }
            }
            gq_scores[tid] = dot;
            gq_reductions[tid] = dot;
            __syncthreads();
            for (uint stride = 64u; stride > 0u; stride >>= 1) {
                if (tid < stride)
                    gq_reductions[tid] = h3_max(
                        gq_reductions[tid],
                        gq_reductions[tid + stride]);
                __syncthreads();
            }
            if (tid == 0u) {
                float previous_max = gq_online_state[0];
                float maximum = h3_max(previous_max, gq_reductions[0]);
                gq_online_state[2] = gq_online_state[1] > 0.0f ?
                    expf(previous_max - maximum) : 0.0f;
                gq_online_state[0] = maximum;
            }
            __syncthreads();
            float probability = key_row < key_count ?
                expf(gq_scores[tid] - gq_online_state[0]) : 0.0f;
            gq_scores[tid] = probability;
            gq_reductions[tid] = probability;
            __syncthreads();
            for (uint stride = 64u; stride > 0u; stride >>= 1) {
                if (tid < stride)
                    gq_reductions[tid] += gq_reductions[tid + stride];
                __syncthreads();
            }
            if (tid == 0u) {
                gq_online_state[1] =
                    gq_online_state[1] * gq_online_state[2] +
                    gq_reductions[0];
            }
            __syncthreads();
            if (tid < head_dim) {
                uint tile_count = key_count - tile_start;
                if (tile_count > 128u) tile_count = 128u;
                float tile_sum = 0.0f;
                for (uint offset = 0u; offset < tile_count; offset++) {
                    uint v_index =
                        ((tile_start + offset) * kv_heads + kv_head) *
                        head_dim + tid;
                    tile_sum = fmaf(gq_scores[offset],
                                   H3_BF16_TO_F32(gq_v[v_index]),
                                   tile_sum);
                }
                accumulator = fmaf(accumulator, gq_online_state[2], tile_sum);
            }
            __syncthreads();
        }
        if (tid < head_dim) {
            gq_out[q_base + tid] = uint16_t(h3_f32_to_bf16(
                accumulator / gq_online_state[1]));
        }
        return;
    }

    float local_max = -3.402823466e+38f;
    for (uint key_row = tid; key_row < key_count; key_row += 128u) {
        uint k_base = (key_row * kv_heads + kv_head) * head_dim;
        float dot = 0.0f;
        for (uint d = 0u; d < head_dim; d++) {
            dot = fmaf(gq_shared_query[d],
                      H3_BF16_TO_F32(gq_k[k_base + d]), dot);
        }
        gq_scores[key_row] = dot;
        local_max = h3_max(local_max, dot);
    }
    gq_reductions[tid] = local_max;
    __syncthreads();
    for (uint stride = 64u; stride > 0u; stride >>= 1) {
        if (tid < stride)
            gq_reductions[tid] = h3_max(gq_reductions[tid],
                                     gq_reductions[tid + stride]);
        __syncthreads();
    }
    float maximum = gq_reductions[0];
    float local_sum = 0.0f;
    for (uint key_row = tid; key_row < key_count; key_row += 128u) {
        float probability = expf(gq_scores[key_row] - maximum);
        gq_scores[key_row] = probability;
        local_sum += probability;
    }
    gq_reductions[tid] = local_sum;
    __syncthreads();
    for (uint stride = 64u; stride > 0u; stride >>= 1) {
        if (tid < stride) gq_reductions[tid] += gq_reductions[tid + stride];
        __syncthreads();
    }
    float inverse_sum = 1.0f / gq_reductions[0];
    for (uint d = tid; d < head_dim; d += 128u) {
        float sum = 0.0f;
        for (uint key_row = 0u; key_row < key_count; key_row++) {
            uint v_index = (key_row * kv_heads + kv_head) * head_dim + d;
            sum = fmaf(gq_scores[key_row] * inverse_sum,
                      H3_BF16_TO_F32(gq_v[v_index]), sum);
        }
        gq_out[q_base + d] = uint16_t(h3_f32_to_bf16(sum));
    }

}

__global__ void main_linear_f32(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    float *lf_b = static_cast<float *>(b2);
    float *lf_in = static_cast<float *>(b0);
    float *lf_out = static_cast<float *>(b3);
    float *lf_w = static_cast<float *>(b1);

    uint column = (blockIdx.x * blockDim.x + threadIdx.x);
    uint row = (blockIdx.y * blockDim.y + threadIdx.y);
    if (row >= args.rows || column >= args.output_dim) return;
    float sum = args.has_bias != 0u ? lf_b[column] : 0.0f;
    for (uint k = 0u; k < args.input_dim; k++) {
        sum = fmaf(lf_in[row * args.input_dim + k],
                  lf_w[column * args.input_dim + k], sum);
    }
    lf_out[row * args.output_dim + column] = sum;

}

__global__ void main_scale_add_f32(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    float *s_branch = static_cast<float *>(b1);
    float *s_out = static_cast<float *>(b3);
    float *s_res = static_cast<float *>(b0);
    float *s_scale = static_cast<float *>(b2);

    uint column = (blockIdx.x * blockDim.x + threadIdx.x);
    uint row = (blockIdx.y * blockDim.y + threadIdx.y);
    if (row >= args.rows || column >= args.width) return;
    uint index = row * args.width + column;
    s_out[index] = fmaf(s_branch[index], s_scale[column],
                            s_res[index]);

}

__global__ void main_swiglu_f32(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    float *swif_in = static_cast<float *>(b0);
    float *swif_out = static_cast<float *>(b1);

    uint column = (blockIdx.x * blockDim.x + threadIdx.x);
    uint row = (blockIdx.y * blockDim.y + threadIdx.y);
    if (row >= args.rows || column >= args.width) return;
    uint base = row * args.width * 2u;
    float gate = swif_in[base + column];
    float up = swif_in[base + args.width + column];
    swif_out[row * args.width + column] =
        gate / (1.0f + expf(-gate)) * up;

}

__global__ void main_video_qkv_rope_f32(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    float *vcos = static_cast<float *>(b1);
    float *vk_out = static_cast<float *>(b4);
    float *vq_out = static_cast<float *>(b3);
    float *vqkv_in = static_cast<float *>(b0);
    float *vsin = static_cast<float *>(b2);
    float *vv_out = static_cast<float *>(b5);

    uint dimension = (blockIdx.x * blockDim.x + threadIdx.x);
    uint head = (blockIdx.y * blockDim.y + threadIdx.y);
    uint row = (blockIdx.z * blockDim.z + threadIdx.z);
    uint head_dim = args.input_dim;
    uint heads = args.width;
    uint sequence = args.rows;
    uint rope_half = args.output_dim;
    if (dimension >= head_dim || head >= heads || row >= sequence) return;
    uint base = (row * heads + head) * head_dim * 3u;
    float q_sum = 0.0f, k_sum = 0.0f;
    for (uint d = 0u; d < head_dim; d++) {
        float q = vqkv_in[base + d];
        float k = vqkv_in[base + head_dim + d];
        q_sum = fmaf(q, q, q_sum);
        k_sum = fmaf(k, k, k_sum);
    }
    float qi = h3_rsqrt(q_sum / float(head_dim) + args.epsilon);
    float ki = h3_rsqrt(k_sum / float(head_dim) + args.epsilon);
    float q0 = vqkv_in[base + dimension] * qi;
    float k0 = vqkv_in[base + head_dim + dimension] * ki;
    if (dimension < rope_half) {
        uint pair = dimension + rope_half;
        float q1 = vqkv_in[base + pair] * qi;
        float k1 = vqkv_in[base + head_dim + pair] * ki;
        float c = vcos[row * rope_half + dimension];
        float s = vsin[row * rope_half + dimension];
        q0 = q0 * c - q1 * s;
        k0 = k0 * c - k1 * s;
    } else if (dimension < rope_half * 2u) {
        uint pair = dimension - rope_half;
        float q1 = vqkv_in[base + pair] * qi;
        float k1 = vqkv_in[base + head_dim + pair] * ki;
        float c = vcos[row * rope_half + pair];
        float s = vsin[row * rope_half + pair];
        q0 = q0 * c + q1 * s;
        k0 = k0 * c + k1 * s;
    }
    uint output_index = (row * heads + head) * head_dim + dimension;
    vq_out[output_index] = q0;
    vk_out[output_index] = k0;
    vv_out[output_index] = vqkv_in[base + head_dim * 2u + dimension];

}

__global__ void main_vae_encoder_pad_f32(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    float *vpad_in = static_cast<float *>(b0);
    float *vpad_out = static_cast<float *>(b1);

    uint channel = (blockIdx.x * blockDim.x + threadIdx.x);
    uint out_x = (blockIdx.y * blockDim.y + threadIdx.y);
    uint plane = (blockIdx.z * blockDim.z + threadIdx.z);
    uint depth = args.conv_depth;
    uint height = args.conv_height;
    uint width = args.conv_width;
    uint channels = args.conv_in_channels;
    uint depth_front = args.pad_depth_front;
    uint height_before = args.pad_height_before;
    uint height_after = args.pad_height_after;
    uint width_before = args.pad_width_before;
    uint width_after = args.pad_width_after;
    uint out_height = height + height_before + height_after;
    uint out_width = width + width_before + width_after;
    uint out_depth = depth + depth_front;
    if (channel >= channels || out_x >= out_width ||
        plane >= args.conv_batch * out_depth * out_height) return;
    uint out_y = plane % out_height;
    uint temporal_plane = plane / out_height;
    uint out_t = temporal_plane % out_depth;
    uint batch = temporal_plane / out_depth;
    uint destination = ((((batch * out_depth + out_t) * out_height + out_y) *
                         out_width + out_x) * channels + channel);
    if (out_t < depth_front) {
        vpad_out[destination] = 0.0f;
        return;
    }
    int source_y = int(out_y) - int(height_before);
    if (source_y < 0) source_y = -source_y;
    if (source_y >= int(height))
        source_y = 2 * int(height) - source_y - 2;
    int source_x = int(out_x) - int(width_before);
    if (source_x < 0) source_x = -source_x;
    if (source_x >= int(width))
        source_x = 2 * int(width) - source_x - 2;
    uint source_t = out_t - depth_front;
    uint source = ((((batch * depth + source_t) * height + uint(source_y)) *
                    width + uint(source_x)) * channels + channel);
    vpad_out[destination] = vpad_in[source];

}

__global__ void main_vae_encoder_group_norm_silu_f32(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    float *gn_b = static_cast<float *>(b2);
    float *gn_in = static_cast<float *>(b0);
    float *gn_out = static_cast<float *>(b3);
    float *gn_w = static_cast<float *>(b1);
    __shared__ float gn_reductions[256];

    uint row = blockIdx.x;
    uint tid = threadIdx.x;
    uint groups = args.conv_out_channels;
    uint channels = args.conv_in_channels;
    uint height = args.conv_height;
    uint width = args.conv_width;
    uint rows = args.conv_batch * args.conv_depth * groups;
    if (row >= rows) return;
    uint channels_per_group = channels / groups;
    uint group_index = row % groups;
    uint temporal_plane = row / groups;
    uint elements = height * width * channels_per_group;
    float local = 0.0f;
    for (uint index = tid; index < elements; index += 256u) {
        uint spatial = index / channels_per_group;
        uint channel = group_index * channels_per_group +
                       index % channels_per_group;
        uint source = (temporal_plane * height * width + spatial) * channels +
                      channel;
        local += gn_in[source];
    }
    gn_reductions[tid] = local;
    __syncthreads();
    for (uint stride = 128u; stride > 0u; stride >>= 1) {
        if (tid < stride) gn_reductions[tid] += gn_reductions[tid + stride];
        __syncthreads();
    }
    float mean = gn_reductions[0] / float(elements);
    local = 0.0f;
    for (uint index = tid; index < elements; index += 256u) {
        uint spatial = index / channels_per_group;
        uint channel = group_index * channels_per_group +
                       index % channels_per_group;
        uint source = (temporal_plane * height * width + spatial) * channels +
                      channel;
        float centered = gn_in[source] - mean;
        local = fmaf(centered, centered, local);
    }
    gn_reductions[tid] = local;
    __syncthreads();
    for (uint stride = 128u; stride > 0u; stride >>= 1) {
        if (tid < stride) gn_reductions[tid] += gn_reductions[tid + stride];
        __syncthreads();
    }
    float inverse = h3_rsqrt(gn_reductions[0] / float(elements) +
                                args.epsilon);
    for (uint index = tid; index < elements; index += 256u) {
        uint spatial = index / channels_per_group;
        uint channel = group_index * channels_per_group +
                       index % channels_per_group;
        uint destination =
            (temporal_plane * height * width + spatial) * channels + channel;
        float value = (gn_in[destination] - mean) * inverse *
                          gn_w[channel] +
                      gn_b[channel];
        gn_out[destination] = value / (1.0f + expf(-value));
    }

}

__global__ void main_sdpa_f32(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    float *sdpf_k = static_cast<float *>(b1);
    float *sdpf_out = static_cast<float *>(b3);
    float *sdpf_q = static_cast<float *>(b0);
    float *sdpf_v = static_cast<float *>(b2);

    uint head = (blockIdx.x * blockDim.x + threadIdx.x);
    uint row = (blockIdx.y * blockDim.y + threadIdx.y);
    uint seq = args.rows;
    uint heads = args.width;
    uint dim = args.input_dim;
    if (row >= seq || head >= heads) return;
    float scale = args.left_scale;
    uint qbase = (row * heads + head) * dim;
    float maxv = -3.402823466e+38f;
    for (uint s = 0u; s < seq; s++) {
        uint kbase = (s * heads + head) * dim;
        float dot = 0.0f;
        for (uint d = 0u; d < dim; d++) {
            dot = fmaf(sdpf_q[qbase + d], sdpf_k[kbase + d], dot);
        }
        dot *= scale;
        maxv = h3_max(maxv, dot);
    }
    float sum = 0.0f;
    for (uint s = 0u; s < seq; s++) {
        uint kbase = (s * heads + head) * dim;
        float dot = 0.0f;
        for (uint d = 0u; d < dim; d++) {
            dot = fmaf(sdpf_q[qbase + d], sdpf_k[kbase + d], dot);
        }
        sum += expf(dot * scale - maxv);
    }
    for (uint d = 0u; d < dim; d++) {
        float acc = 0.0f;
        for (uint s = 0u; s < seq; s++) {
            uint kbase = (s * heads + head) * dim;
            float dot = 0.0f;
            for (uint k = 0u; k < dim; k++) {
                dot = fmaf(sdpf_q[qbase + k],
                          sdpf_k[kbase + k], dot);
            }
            acc = fmaf(expf(dot * scale - maxv), sdpf_v[kbase + d], acc);
        }
        uint oindex = args.grouped != 0u ?
            (head * seq + row) * dim + d : qbase + d;
        sdpf_out[oindex] = acc / sum;
    }

}

__global__ void main_sdpa_flash_f32(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    float *flf_k = static_cast<float *>(b1);
    float *flf_out = static_cast<float *>(b3);
    float *flf_q = static_cast<float *>(b0);
    float *flf_v = static_cast<float *>(b2);
    __shared__ float fl_acc[128];
    __shared__ float fl_dots[128];
    __shared__ float fl_max;
    __shared__ float fl_old_max;
    __shared__ float fl_q_shared[128];
    __shared__ float fl_sum;

    uint head = blockIdx.x;
    uint row = blockIdx.y;
    uint d = threadIdx.x;
    uint seq = args.rows;
    uint heads = args.width;
    uint dim = args.input_dim;
    if (row >= seq || head >= heads || d >= dim) return;
    float scale = args.left_scale;
    uint qbase = (row * heads + head) * dim;
    fl_q_shared[d] = flf_q[qbase + d];
    fl_acc[d] = 0.0f;
    if (d == 0u) {
        fl_max = -3.402823466e+38f;
        fl_sum = 0.0f;
    }
    __syncthreads();
    for (uint s = 0u; s < seq; s++) {
        uint kbase = (s * heads + head) * dim;
        fl_dots[d] = fmaf(fl_q_shared[d], flf_k[kbase + d], 0.0f);
        __syncthreads();
        for (uint stride = 64u; stride > 0u; stride >>= 1) {
            if (d < stride) fl_dots[d] += fl_dots[d + stride];
            __syncthreads();
        }
        float dot = fl_dots[0] * scale;
        if (d == 0u) {
            float new_max = h3_max(fl_max, dot);
            fl_old_max = fl_max;
            fl_max = new_max;
            fl_sum = fl_sum * expf(fl_old_max - new_max) +
                     expf(dot - new_max);
        }
        __syncthreads();
        float p = expf(fl_old_max - fl_max);
        float w = expf(fl_dots[0] * scale - fl_max);
        fl_acc[d] = fl_acc[d] * p + w * flf_v[kbase + d];
        __syncthreads();
    }
    uint oindex = args.grouped != 0u ?
        (head * seq + row) * dim + d : qbase + d;
    flf_out[oindex] = fl_acc[d] / fl_sum;

}

__global__ void main_conv3d_f32(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    float *cv_b = static_cast<float *>(b2);
    float *cv_in = static_cast<float *>(b0);
    float *cv_out = static_cast<float *>(b3);
    float *cv_w = static_cast<float *>(b1);

    uint out_x = (blockIdx.x * blockDim.x + threadIdx.x);
    uint plane = (blockIdx.z * blockDim.z + threadIdx.z);
    uint batch = args.conv_batch;
    uint depth = args.conv_depth;
    uint height = args.conv_height;
    uint width = args.conv_width;
    uint in_channels = args.conv_in_channels;
    uint out_channels = args.conv_out_channels;
    uint kd = args.conv_kernel_depth;
    uint kh = args.conv_kernel_height;
    uint kw = args.conv_kernel_width;
    uint sd = args.conv_stride_depth;
    uint sh = args.conv_stride_height;
    uint sw = args.conv_stride_width;
    uint output_depth = (depth - kd) / sd + 1u;
    uint output_height = (height - kh) / sh + 1u;
    uint output_width = (width - kw) / sw + 1u;
    uint spatial = plane % (output_depth * output_height);
    uint out_t = spatial / output_height;
    uint out_h = spatial % output_height;
    uint batch_index = plane / (output_depth * output_height);
    if (batch_index >= batch || out_t >= output_depth ||
        out_h >= output_height || out_x >= output_width) return;
    for (uint oc = 0u; oc < out_channels; oc++) {
        float sum = args.has_bias != 0u ? cv_b[oc] : 0.0f;
        for (uint kt = 0u; kt < kd; kt++) {
            for (uint khh = 0u; khh < kh; khh++) {
                for (uint kww = 0u; kww < kw; kww++) {
                    for (uint ic = 0u; ic < in_channels; ic++) {
                        uint in_t = out_t * sd + kt;
                        uint in_h = out_h * sh + khh;
                        uint in_x = out_x * sw + kww;
                        uint input_index =
                            ((((batch_index * depth + in_t) * height + in_h) *
                              width + in_x) * in_channels + ic);
                        uint weight_index =
                            ((((oc * in_channels + ic) * kd + kt) * kh +
                              khh) * kw + kww);
                        sum = fmaf(cv_in[input_index],
                                  cv_w[weight_index], sum);
                    }
                }
            }
        }
        uint output_index =
            ((((batch_index * output_depth + out_t) * output_height + out_h) *
              output_width + out_x) * out_channels + oc);
        cv_out[output_index] = sum;
    }

}

__global__ void main_weight_norm_f32(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    float *wn_mag = static_cast<float *>(b1);
    float *wn_out = static_cast<float *>(b2);
    float *wn_vec = static_cast<float *>(b0);

    uint row = (blockIdx.x * blockDim.x + threadIdx.x);
    if (row >= args.rows) return;
    uint base = row * args.width;
    float square_sum = 0.0f;
    for (uint index = 0u; index < args.width; index++) {
        float value = wn_vec[base + index];
        square_sum = fmaf(value, value, square_sum);
    }
    float scale = wn_mag[row] * h3_rsqrt(square_sum);
    for (uint index = 0u; index < args.width; index++) {
        wn_out[base + index] = wn_vec[base + index] * scale;
    }

}

__global__ void main_snake1d_f32(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    float *sn_a = static_cast<float *>(b1);
    float *sn_in = static_cast<float *>(b0);
    float *sn_out = static_cast<float *>(b2);

    uint gid = (blockIdx.x * blockDim.x + threadIdx.x);
    if (gid >= args.elements) return;
    float a = sn_a[gid % args.conv_in_channels];
    float x = sn_in[gid];
    float wave = sinf(a * x);
    sn_out[gid] = x + wave * wave / (a + 1e-9f);

}

__global__ void main_alias_free_snake_f32(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    float *af_alpha = static_cast<float *>(b1);
    float *af_beta = static_cast<float *>(b2);
    float *af_down = static_cast<float *>(b4);
    float *af_in = static_cast<float *>(b0);
    float *af_out = static_cast<float *>(b5);
    float *af_up = static_cast<float *>(b3);

    uint channel = (blockIdx.x * blockDim.x + threadIdx.x);
    uint time = (blockIdx.y * blockDim.y + threadIdx.y);
    uint batch = (blockIdx.z * blockDim.z + threadIdx.z);
    uint channels = args.conv_in_channels;
    uint length = args.conv_depth;
    if (channel >= channels || time >= length || batch >= args.conv_batch)
        return;
    float alpha = expf(af_alpha[channel]);
    float beta = expf(af_beta[channel]);
    float result = 0.0f;
    for (int down_k = 0; down_k < 12; down_k++) {
        int up_time = int(time * 2u) + down_k - 5;
        up_time = h3_clamp(up_time, 0, int(length * 2u) - 1);
        int raw_time = up_time + 15;
        float upsampled = 0.0f;
        for (int up_k = 0; up_k < 12; up_k++) {
            int numerator = raw_time - up_k;
            if (numerator < 0 || (numerator & 1) != 0) continue;
            int padded_time = numerator / 2;
            int source_time = h3_clamp(padded_time - 5, 0, int(length) - 1);
            uint source = (batch * length + uint(source_time)) * channels +
                          channel;
            upsampled = fmaf(af_in[source],
                            2.0f * af_up[uint(up_k)], upsampled);
        }
        float sine = sinf(alpha * upsampled);
        float activated = upsampled + sine * sine / (beta + 1e-9f);
        result = fmaf(activated, af_down[uint(down_k)], result);
    }
    uint destination = (batch * length + time) * channels + channel;
    af_out[destination] = result;

}

__global__ void main_audio_qkv_split_f32(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    float *aqs_k = static_cast<float *>(b5);
    float *aqs_kb = static_cast<float *>(b2);
    float *aqs_q = static_cast<float *>(b4);
    float *aqs_qb = static_cast<float *>(b1);
    float *aqs_qkv = static_cast<float *>(b0);
    float *aqs_v = static_cast<float *>(b6);
    float *aqs_vb = static_cast<float *>(b3);

    uint gid = (blockIdx.x * blockDim.x + threadIdx.x);
    if (gid >= args.elements) return;
    uint width = args.conv_width * args.conv_height;
    uint column = gid % width;
    uint row = gid / width;
    uint base = row * width * 3u;
    aqs_q[gid] = aqs_qkv[base + column] + aqs_qb[column];
    aqs_k[gid] = aqs_qkv[base + width + column] + aqs_kb[column];
    aqs_v[gid] = aqs_qkv[base + width * 2u + column] +
                      aqs_vb[column];

}

__global__ void main_audio_attention_pool_f32(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    float *ap_in = static_cast<float *>(b0);
    float *ap_out = static_cast<float *>(b1);

    uint gid = (blockIdx.x * blockDim.x + threadIdx.x);
    if (gid >= args.elements) return;
    uint column = gid % args.conv_in_channels;
    uint row = gid / args.conv_in_channels;
    uint pool = args.conv_height / args.conv_in_channels;
    float sum = 0.0f;
    for (uint head = 0u; head < args.conv_width; head++) {
        uint base = (row * args.conv_width + head) *
                        args.conv_height +
                    column * pool;
        for (uint item = 0u; item < pool; item++)
            sum += ap_in[base + item];
    }
    ap_out[gid] = sum / float(args.conv_width * pool);

}

__global__ void main_conv1d_stride_f32(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    float *c1_b = static_cast<float *>(b2);
    float *c1_in = static_cast<float *>(b0);
    float *c1_out = static_cast<float *>(b3);
    float *c1_w = static_cast<float *>(b1);

    uint oc = (blockIdx.x * blockDim.x + threadIdx.x);
    uint time = (blockIdx.y * blockDim.y + threadIdx.y);
    uint batch = (blockIdx.z * blockDim.z + threadIdx.z);
    uint length = args.conv_depth;
    uint in_channels = args.conv_in_channels;
    uint out_channels = args.conv_out_channels;
    uint kernel = args.conv_kernel_width;
    uint stride = args.conv_stride_width;
    uint padding = args.conv_stride_height;
    uint dilation = args.conv_stride_depth;
    uint effective = dilation * (kernel - 1u) + 1u;
    uint output_length = (length + 2u * padding - effective) / stride + 1u;
    if (oc >= out_channels || time >= output_length ||
        batch >= args.conv_batch)
        return;
    float sum = args.has_bias != 0u ? c1_b[oc] : 0.0f;
    for (uint ic = 0u; ic < in_channels; ic++) {
        for (uint k = 0u; k < kernel; k++) {
            int source = int(time * stride) + int(k * dilation) -
                         int(padding);
            if (source < 0 || source >= int(length)) continue;
            uint input_index =
                (batch * length + uint(source)) * in_channels + ic;
            uint weight_index = (oc * in_channels + ic) * kernel + k;
            sum = fmaf(c1_in[input_index], c1_w[weight_index], sum);
        }
    }
    uint output_index =
        (batch * output_length + time) * out_channels + oc;
    c1_out[output_index] = sum;

}

__global__ void main_conv_transpose1d_f32(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
