    uint kernel = args.conv_kernel_width;
    uint stride = args.conv_stride_width;
    uint padding = args.conv_stride_height;
    uint output_length = (length - 1u) * stride + kernel - 2u * padding;
    if (oc >= out_channels || time >= output_length ||
        batch >= args.conv_batch)
        return;
    float sum = args.has_bias != 0u ? c1_b[oc] : 0.0f;
    for (uint ic = 0u; ic < in_channels; ic++) {
        for (uint k = 0u; k < kernel; k++) {
            int numerator = int(time) + int(padding) - int(k);
            if (numerator < 0 || numerator % int(stride) != 0) continue;
            uint source = uint(numerator) / stride;
            if (source >= length) continue;
            uint input_index = (batch * length + source) * in_channels + ic;
            /* IOK weight layout: [in_ch][out_ch][kernel] */
            uint weight_index = (ic * out_channels + oc) * kernel + k;
            sum = fmaf(c1_in[input_index], c1_w[weight_index], sum);
        }
    }
    uint output_index =
        (batch * output_length + time) * out_channels + oc;
    c1_out[output_index] = sum;

}

__global__ void main_sdpa_causal_f32(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    float *sdpc_k = static_cast<float *>(b1);
    float *sdpc_out = static_cast<float *>(b3);
    float *sdpc_q = static_cast<float *>(b0);
    float *sdpc_v = static_cast<float *>(b2);

    uint head = (blockIdx.x * blockDim.x + threadIdx.x);
    uint row = (blockIdx.y * blockDim.y + threadIdx.y);
    uint batch = (blockIdx.z * blockDim.z + threadIdx.z);
    uint seq = args.rows;
    uint heads = args.width;
    uint dim = args.input_dim;
    uint batches = args.conv_batch;
    if (row >= seq || head >= heads || batch >= batches) return;
    float scale = args.left_scale;
    uint qbase = ((batch * seq + row) * heads + head) * dim;
    float maxv = -3.402823466e+38f;
    for (uint s = 0u; s <= row; s++) {
        uint kbase = ((batch * seq + s) * heads + head) * dim;
        float dot = 0.0f;
        for (uint d = 0u; d < dim; d++) {
            dot = fmaf(sdpc_q[qbase + d], sdpc_k[kbase + d], dot);
        }
        dot *= scale;
        maxv = h3_max(maxv, dot);
    }
    float sum = 0.0f;
    for (uint s = 0u; s <= row; s++) {
        uint kbase = ((batch * seq + s) * heads + head) * dim;
        float dot = 0.0f;
        for (uint d = 0u; d < dim; d++) {
            dot = fmaf(sdpc_q[qbase + d], sdpc_k[kbase + d], dot);
        }
        sum += expf(dot * scale - maxv);
    }
    for (uint d = 0u; d < dim; d++) {
        float acc = 0.0f;
        for (uint s = 0u; s <= row; s++) {
            uint kbase = ((batch * seq + s) * heads + head) * dim;
            float dot = 0.0f;
            for (uint k = 0u; k < dim; k++) {
                dot = fmaf(sdpc_q[qbase + k],
                          sdpc_k[kbase + k], dot);
            }
            acc = fmaf(expf(dot * scale - maxv), sdpc_v[kbase + d], acc);
        }
        sdpc_out[qbase + d] = acc / sum;
    }

}

__global__ void main_vision_qkv_rope_bf16(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    uint16_t *vis_cos = static_cast<uint16_t *>(b1);
    uint16_t *vis_in = static_cast<uint16_t *>(b0);
    uint16_t *vis_k = static_cast<uint16_t *>(b4);
    uint16_t *vis_q = static_cast<uint16_t *>(b3);
    uint16_t *vis_sin = static_cast<uint16_t *>(b2);
    uint16_t *vis_v = static_cast<uint16_t *>(b5);

    uint dimension = (blockIdx.x * blockDim.x + threadIdx.x);
    uint head = (blockIdx.y * blockDim.y + threadIdx.y);
    uint row = (blockIdx.z * blockDim.z + threadIdx.z);
    uint head_dim = args.input_dim;
    uint heads = args.width;
    uint sequence = args.rows;
    uint half_dim = args.output_dim;
    if (dimension >= head_dim || head >= heads || row >= sequence) return;
    uint inner = heads * head_dim;
    uint row_base = row * inner * 3u;
    uint q_base = row_base + head * head_dim;
    uint k_base = row_base + inner + head * head_dim;
    uint v_base = row_base + inner * 2u + head * head_dim;
    uint rope_index = row * half_dim + dimension % half_dim;
    float c = H3_BF16_TO_F32(vis_cos[rope_index]);
    float s = H3_BF16_TO_F32(vis_sin[rope_index]);
    uint pair = dimension < half_dim ? dimension + half_dim :
                                        dimension - half_dim;
    float q0 = H3_BF16_TO_F32(vis_in[q_base + dimension]);
    float k0 = H3_BF16_TO_F32(vis_in[k_base + dimension]);
    float q1 = H3_BF16_TO_F32(vis_in[q_base + pair]);
    float k1 = H3_BF16_TO_F32(vis_in[k_base + pair]);
    float qr = dimension < half_dim ? q0 * c - q1 * s : q0 * c + q1 * s;
    float kr = dimension < half_dim ? k0 * c - k1 * s : k0 * c + k1 * s;
    uint output_index = (row * heads + head) * head_dim + dimension;
    vis_q[output_index] = uint16_t(h3_f32_to_bf16(qr));
    vis_k[output_index] = uint16_t(h3_f32_to_bf16(kr));
    vis_v[output_index] = vis_in[v_base + dimension];

}

__global__ void main_quantize_rows_bf16_i8(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    uint16_t *q_in = static_cast<uint16_t *>(b0);
    int8_t *q_out = static_cast<int8_t *>(b1);
    float *q_scales = static_cast<float *>(b2);
    __shared__ float q_reductions[256];

    uint row = blockIdx.x;
    uint tid = threadIdx.x;
    uint base = row * args.width;
    if (row >= args.rows) {
        for (uint column = tid; column < args.width; column += 256u) {
            q_out[base + column] = int8_t(0);
        }
        if (tid == 0u) q_scales[row] = 1.0f;
        return;
    }
    float local_max = 0.0f;
    for (uint column = tid; column < args.width; column += 256u) {
        local_max = h3_max(local_max, fabsf(H3_BF16_TO_F32(q_in[base + column])));
    }
    q_reductions[tid] = local_max;
    __syncthreads();
    for (uint stride = 128u; stride > 0u; stride >>= 1) {
        if (tid < stride) q_reductions[tid] = h3_max(q_reductions[tid],
                                                  q_reductions[tid + stride]);
        __syncthreads();
    }
    float max_abs = q_reductions[0];
    float clipped_max = max_abs * args.left_scale;
    float scale = clipped_max > 0.0f ? clipped_max / 127.0f : 1.0f / 127.0f;
    float inverse = clipped_max > 0.0f ? 127.0f / clipped_max : 127.0f;
    if (tid == 0u) q_scales[row] = scale;
    for (uint column = tid; column < args.width; column += 256u) {
        int quantized = int(rintf(H3_BF16_TO_F32(q_in[base + column]) *
                                 inverse));
        q_out[base + column] = int8_t(h3_clamp(quantized, -127, 127));
    }

}

__global__ void main_linear_int8_bf16(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    int8_t *l8_in = static_cast<int8_t *>(b0);
    float *l8_is = static_cast<float *>(b2);
    uint16_t *l8_out = static_cast<uint16_t *>(b4);
    int8_t *l8_w = static_cast<int8_t *>(b1);
    float *l8_ws = static_cast<float *>(b3);
    __shared__ int lin8_in_tile[16][16];
    __shared__ int lin8_w_tile[16][16];

    uint column = blockIdx.x * 16u + threadIdx.x;
    uint row = blockIdx.y * 16u + threadIdx.y;
    int acc = 0;
    uint tile_count = (args.input_dim + 15u) / 16u;
    for (uint tile = 0u; tile < tile_count; tile++) {
        uint input_k = tile * 16u + threadIdx.x;
        lin8_in_tile[threadIdx.y][threadIdx.x] =
            (row < args.rows && input_k < args.input_dim) ?
            int(l8_in[row * args.input_dim + input_k]) : 0;
        uint weight_k = tile * 16u + threadIdx.y;
        lin8_w_tile[threadIdx.y][threadIdx.x] =
            (column < args.output_dim && weight_k < args.input_dim) ?
            int(l8_w[column * args.input_dim + weight_k]) : 0;
        __syncthreads();
        for (uint k = 0u; k < 16u; k++) {
            acc += lin8_in_tile[threadIdx.y][k] *
                   lin8_w_tile[k][threadIdx.x];
        }
        __syncthreads();
    }
    if (row < args.rows && column < args.output_dim) {
        float dequant = float(acc) * l8_is[row] * l8_ws[column];
        l8_out[row * args.output_dim + column] =
            uint16_t(h3_f32_to_bf16(dequant));
    }

}

__global__ void main_fc1_swiglu_int8_bf16(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    int8_t *l8_in = static_cast<int8_t *>(b0);
    float *l8_is = static_cast<float *>(b2);
    uint16_t *l8_out = static_cast<uint16_t *>(b4);
    int8_t *l8_w = static_cast<int8_t *>(b1);
    float *l8_ws = static_cast<float *>(b3);
    __shared__ int fc1_g_tile[16][16];
    __shared__ int fc1_in_tile[16][16];
    __shared__ int fc1_u_tile[16][16];

    uint column = blockIdx.x * 16u + threadIdx.x;
    uint row = blockIdx.y * 16u + threadIdx.y;
    uint hidden = args.output_dim;
    int acc_gate = 0;
    int acc_up = 0;
    uint tile_count = (args.input_dim + 15u) / 16u;
    for (uint tile = 0u; tile < tile_count; tile++) {
        uint input_k = tile * 16u + threadIdx.x;
        fc1_in_tile[threadIdx.y][threadIdx.x] =
            (row < args.rows && input_k < args.input_dim) ?
            int(l8_in[row * args.input_dim + input_k]) : 0;
        uint weight_k = tile * 16u + threadIdx.y;
        int gate_w = (column < hidden && weight_k < args.input_dim) ?
            int(l8_w[column * args.input_dim + weight_k]) : 0;
        int up_w = (column < hidden && weight_k < args.input_dim) ?
            int(l8_w[(hidden + column) * args.input_dim +
                          weight_k]) : 0;
        fc1_g_tile[threadIdx.y][threadIdx.x] = gate_w;
        fc1_u_tile[threadIdx.y][threadIdx.x] = up_w;
        __syncthreads();
        for (uint k = 0u; k < 16u; k++) {
            int value = fc1_in_tile[threadIdx.y][k];
            acc_gate += value * fc1_g_tile[k][threadIdx.x];
            acc_up += value * fc1_u_tile[k][threadIdx.x];
        }
        __syncthreads();
    }
    if (row < args.rows && column < hidden) {
        float input_scale = l8_is[row];
        /* Metal materializes the gate cooperative fragment in BF16 before
         * applying SiLU; the up fragment remains F32 until the final product. */
        float gate = H3_BF16_TO_F32(h3_f32_to_bf16(
            float(acc_gate) * input_scale * l8_ws[column]));
        float up = float(acc_up) * input_scale * l8_ws[hidden + column];
        l8_out[row * hidden + column] = uint16_t(h3_f32_to_bf16(
            gate / (1.0f + expf(-gate)) * up));
    }

}

__global__ void main_gate_adaln_quantize_int8(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    uint16_t *ia_branch = static_cast<uint16_t *>(b1);
    uint16_t *ia_gated = static_cast<uint16_t *>(b6);
    uint16_t *ia_gmod = static_cast<uint16_t *>(b2);
    uint32_t *ia_map = static_cast<uint32_t *>(b3);
    uint16_t *ia_nmod = static_cast<uint16_t *>(b5);
    int8_t *ia_out = static_cast<int8_t *>(b7);
    uint16_t *ia_res = static_cast<uint16_t *>(b0);
    float *ia_scales = static_cast<float *>(b8);
    uint16_t *ia_w = static_cast<uint16_t *>(b4);
    __shared__ float ia_reductions[256];
    __shared__ uint16_t ia_values[5376];

    uint row = blockIdx.x;
    uint tid = threadIdx.x;
    uint width = args.width;
    if (row >= args.rows) {
        uint qbase = row * width;
        for (uint column = tid; column < width; column += 256u)
            ia_out[qbase + column] = int8_t(0);
        if (tid == 0u) ia_scales[row] = 1.0f;
        return;
    }
    uint base = ia_map[row] * args.slots * width;
    uint row_base = row * width;
    float local_sum = 0.0f;
    for (uint column = tid; column < width; column += 256u) {
        uint index = row_base + column;
        float gate = H3_BF16_TO_F32(
            ia_gmod[base + args.gate_slot * width + column]);
        uint16_t gated = uint16_t(h3_f32_to_bf16(
            fmaf(H3_BF16_TO_F32(ia_branch[index]), gate,
                H3_BF16_TO_F32(ia_res[index]))));
        ia_gated[index] = gated;
        ia_values[column] = gated;
        float value = H3_BF16_TO_F32(gated);
        local_sum = fmaf(value, value, local_sum);
    }
    ia_reductions[tid] = local_sum;
    __syncthreads();
    for (uint stride = 128u; stride > 0u; stride >>= 1) {
        if (tid < stride) ia_reductions[tid] += ia_reductions[tid + stride];
        __syncthreads();
    }
    float inverse = h3_rsqrt(ia_reductions[0] / float(width) +
                                args.epsilon);
    float local_max = 0.0f;
    for (uint column = tid; column < width; column += 256u) {
        float normalized = H3_BF16_TO_F32(ia_values[column]) * inverse *
            H3_BF16_TO_F32(ia_w[column]);
        float shift = H3_BF16_TO_F32(
            ia_nmod[base + args.shift_slot * width + column]);
        float scale = H3_BF16_TO_F32(
            ia_nmod[base + args.scale_slot * width + column]);
        uint16_t value = uint16_t(h3_f32_to_bf16(
            fmaf(normalized, 1.0f + scale, shift)));
        ia_values[column] = value;
        local_max = h3_max(local_max, fabsf(H3_BF16_TO_F32(value)));
    }
    ia_reductions[tid] = local_max;
    __syncthreads();
    for (uint stride = 128u; stride > 0u; stride >>= 1) {
        if (tid < stride) ia_reductions[tid] = h3_max(ia_reductions[tid],
                                                   ia_reductions[tid + stride]);
        __syncthreads();
    }
    float max_abs = ia_reductions[0];
    float output_scale = max_abs > 0.0f ? max_abs / 127.0f : 1.0f / 127.0f;
    float quantize_scale = max_abs > 0.0f ? 127.0f / max_abs : 127.0f;
    if (tid == 0u) ia_scales[row] = output_scale;
    for (uint column = tid; column < width; column += 256u) {
        int value = int(rintf(H3_BF16_TO_F32(ia_values[column]) *
                             quantize_scale));
        ia_out[row_base + column] = int8_t(h3_clamp(value, -127, 127));
    }

}

__global__ void main_quantize_rows_groups_bf16_i8(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    uint16_t *q_in = static_cast<uint16_t *>(b0);
    int8_t *q_out = static_cast<int8_t *>(b1);
    float *q_scales = static_cast<float *>(b2);
    __shared__ float q_reductions[256];

    uint row = blockIdx.x;
    uint tid = threadIdx.x;
    uint columns = args.width;
    uint groups = args.output_dim;
    uint group_size = args.elements;
    uint base = row * columns;
    if (row >= args.rows) {
        for (uint column = tid; column < columns; column += 256u)
            q_out[base + column] = int8_t(0);
        for (uint group = tid; group < groups; group += 256u)
            q_scales[row * groups + group] = 1.0f;
        return;
    }
    for (uint group = 0u; group < groups; group++) {
        uint start = group * group_size;
        float local_max = 0.0f;
        for (uint local = tid; local < group_size; local += 256u)
            local_max = h3_max(local_max,
                            fabsf(H3_BF16_TO_F32(q_in[base + start + local])));
        q_reductions[tid] = local_max;
        __syncthreads();
        for (uint stride = 128u; stride > 0u; stride >>= 1) {
            if (tid < stride) q_reductions[tid] = h3_max(q_reductions[tid],
                                                      q_reductions[tid + stride]);
            __syncthreads();
        }
        float max_abs = q_reductions[0];
        float scale = max_abs > 0.0f ? max_abs / 127.0f : 1.0f / 127.0f;
        float inverse = max_abs > 0.0f ? 127.0f / max_abs : 127.0f;
        if (tid == 0u) {
            q_scales[row * groups + group] = scale;
        }
        for (uint local = tid; local < group_size; local += 256u) {
            int quantized = int(rintf(H3_BF16_TO_F32(q_in[base + start + local]) *
                                     inverse));
            q_out[base + start + local] = int8_t(h3_clamp(quantized, -127, 127));
        }
        __syncthreads();
    }

}

__global__ void main_linear_int8_grouped_bf16(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    int8_t *l8_in = static_cast<int8_t *>(b0);
    float *l8_is = static_cast<float *>(b2);
    uint16_t *l8_out = static_cast<uint16_t *>(b4);
    int8_t *l8_w = static_cast<int8_t *>(b1);
    float *l8_ws = static_cast<float *>(b3);
    __shared__ int lin8_in_tile[16][16];
    __shared__ int lin8_w_tile[16][16];

    uint column = blockIdx.x * 16u + threadIdx.x;
    uint row = blockIdx.y * 16u + threadIdx.y;
    /* args: rows/input_dim/output_dim as usual; width = group size,
     * elements = number of groups. */
    uint groups = args.elements;
    uint group_size = args.width;
    if (groups > 16u) return;
    int acc[16];
    for (uint g = 0u; g < groups; g++) acc[g] = 0;
    uint tile_count = (args.input_dim + 15u) / 16u;
    for (uint tile = 0u; tile < tile_count; tile++) {
        uint input_k = tile * 16u + threadIdx.x;
        lin8_in_tile[threadIdx.y][threadIdx.x] =
            (row < args.rows && input_k < args.input_dim) ?
            int(l8_in[row * args.input_dim + input_k]) : 0;
        uint weight_k = tile * 16u + threadIdx.y;
        lin8_w_tile[threadIdx.y][threadIdx.x] =
            (column < args.output_dim && weight_k < args.input_dim) ?
            int(l8_w[column * args.input_dim + weight_k]) : 0;
        __syncthreads();
        uint group = (tile * 16u) / group_size;
        for (uint k = 0u; k < 16u; k++) {
            acc[group] += lin8_in_tile[threadIdx.y][k] *
                          lin8_w_tile[k][threadIdx.x];
        }
        __syncthreads();
    }
    if (row < args.rows && column < args.output_dim) {
        float total = 0.0f;
        for (uint g = 0u; g < groups; g++) {
            total += float(acc[g]) * l8_is[row * groups + g] *
                     l8_ws[column];
        }
        l8_out[row * args.output_dim + column] =
            uint16_t(h3_f32_to_bf16(total));
    }

}

__global__ void main_quantize_head_major_rows_bf16_i8(h3_cuda_args args, void *b0, void *b1, void *b2, void *b3, void *b4, void *b5, void *b6, void *b7, void *b8, void *b9) {
    uint16_t *q_in = static_cast<uint16_t *>(b0);
    int8_t *q_out = static_cast<int8_t *>(b1);
    float *q_scales = static_cast<float *>(b2);
    __shared__ float q_reductions[256];

    uint row = blockIdx.x;
    uint tid = threadIdx.x;
    uint heads = args.width;
    uint head_dim = args.input_dim;
    uint columns = heads * head_dim;
    uint output_base = row * columns;
    float local_max = 0.0f;
    for (uint column = tid; column < columns; column += 256u) {
        uint head = column / head_dim;
        uint dimension = column - head * head_dim;
        uint source = (head * args.rows + row) * head_dim + dimension;
        local_max = h3_max(local_max,
                        fabsf(H3_BF16_TO_F32(q_in[source])));
    }
    q_reductions[tid] = local_max;
    __syncthreads();
    for (uint stride = 128u; stride > 0u; stride >>= 1) {
        if (tid < stride) q_reductions[tid] = h3_max(q_reductions[tid],
                                                  q_reductions[tid + stride]);
        __syncthreads();
    }
    float max_abs = q_reductions[0];
    float clipped_max = max_abs * args.left_scale;
    float scale = clipped_max > 0.0f ? clipped_max / 127.0f : 1.0f / 127.0f;
    float inverse = clipped_max > 0.0f ? 127.0f / clipped_max : 127.0f;
    if (tid == 0u) q_scales[row] = scale;
    for (uint column = tid; column < columns; column += 256u) {
        uint head = column / head_dim;
        uint dimension = column - head * head_dim;
        uint source = (head * args.rows + row) * head_dim + dimension;
        int quantized = int(rintf(H3_BF16_TO_F32(q_in[source]) *
                                      inverse));
        q_out[output_base + column] =
            int8_t(h3_clamp(quantized, -127, 127));
    }

}


extern "C" int h3_cuda_launch(h3_cuda_kernel kernel, void *stream_handle,
                              const h3_cuda_args *args,
                              void *const buffers[10], uint32_t groups_x,
                              uint32_t groups_y, uint32_t groups_z,
                              char *error, size_t error_size) {
    if (!args || !buffers) {
        if (error && error_size)
            snprintf(error, error_size, "invalid CUDA launch arguments");
